(npl) abaker@casper-login2:/glade/derecho/scratch/abaker/wrf> more py2d.py
# Open a single NetCDF file
import xarray as xr
ds = xr.open_dataset('chunked/wrf2d_c0.nc')

#print out all 2D variables
var_list = []
for var_name, var in ds.variables.items():
	if len(var.dims) == 3: # there’s a time dimension
            if var.dtype != 'int32':
    	        var_list.append(var_name)
    	        print(f"{var_name}&", end="")
#blank line
print()

# print out NaN, extreme value information
for v in var_list:
    if ds[v].isnull().any():
        print(f"{v} has NaN!")
    max_val = ds[v].max(skipna=True)
    min_val = ds[v].min(skipna=True)
    if abs(max_val) > 1e34:
        print(f"{v}: max = {max_val.item()}")
    if abs(min_val) > 1e34:
        print(f"{v}: min = {min_val.item()}")

ds.close()
