#! /usr/bin/env python 
import os 

base_dir = "/glade/campaign/cisl/asap/abaker/wrf/single_vars_wrf_24hr/"

var_list = ["ACECAN",  "LWUPT",  "Q2",  "QVAPOR",  "RAINNCV",  "SNLIQ",  "T2",  "TK",  "U",  "U10",  "V",  "V10"]
#var_list = ["ACECAN"]

#compressor
lossless = 1
gbr = 1
sperr = 1
zfp = 1

#plugins
zfp_plugin = "/glade/work/vanderwb/spack-downstreams/derecho/23.09/opt/spack/h5z-zfp/1.1.1/gcc/13.2.0/d5bw/plugin/"
sperr_plugin = "/glade/work/abaker/compress-libs/zfp_plugin/plugin"
casper_both = "/glade/work/abaker/compress-libs/casper_plugins"

os.environ['HDF5_PLUGIN_PATH'] = casper_both

#loop through variable dirs
for var in var_list:
    print("VARIABLE = ", var)
    var_dir = base_dir + var + "/"
    print(var_dir)
    
    #loop through orig files
    for filename in os.listdir(var_dir + "orig"):
        infile = var_dir + "orig/" + filename

        #Lossless
        if lossless == 1:
            ll_dir = var_dir + "lossless"
            if not os.path.isdir(ll_dir):
                os.system("mkdir " + ll_dir)
                outfile = ll_dir + "/" + filename
                ll_command = "nccopy -d 1 -s " + infile + " " + outfile
                print(ll_command)
                os.system(ll_command)

        #granular bit rounding
        if gbr == 1:
            for i in range(1,6):
                bg_dir = var_dir + "gbr_" + str(i)
                if not os.path.isdir(bg_dir):
                    os.system("mkdir " + bg_dir)
                    outfile =  bg_dir + "/" + filename
                    bg_command = 'ncks  --cmp="gbr,' + str(i) + '|dfl" ' + infile + ' '  + outfile
                    print(bg_command)
                    os.system(bg_command)

        #sperr
        if sperr == 1:
            tol_list = ["pwe1e-1", "pwe1e-2", "pwe1e-3", "pwe1e-4", "pwe1e-5", "psnr100", "psnr50", "psnr75", "psnr125", "psnr150", "psnr175", "psnr2
00", "psnr225"]
            sperr_args = ["3087225450u", "3087443156u","3087660862u", "3087878568u", "3088096274u", "2690908160u", "2687631360u", "2689269760u", "269
2546560u", "2694184960u", "2695823360u", "2697461760u", "2699100160u"]
            for i in range(len(tol_list)):
                sperr_dir = var_dir + "sperr_" + tol_list[i]
                if not os.path.isdir(sperr_dir):
                    os.system("mkdir " + sperr_dir)
                    outfile = sperr_dir + "/" + filename
                    sperr_command = 'nccopy -F *,32028,' + sperr_args[i] + '  '  + infile + ' ' + outfile
                    print(sperr_command)
                    os.system(sperr_command)
                    
        #zfp
        if zfp == 1:
            for i in range(8,23,2):    
                zfp_dir = var_dir + "zfp_p" + str(i)
                if not os.path.isdir(zfp_dir):
                    os.system("mkdir " +zfp_dir)
                    outfile =  zfp_dir + "/" + filename
                    zfp_command = 'nccopy -F "' + var + ',32013,2,0,' + str(i) + '" ' + infile + ' ' + outfile
                    print(zfp_command)
                    os.system(zfp_command)
    
