#! /usr/bin/env python 
import os 

base_dir = "/glade/campaign/cisl/asap/abaker/wrf_update/"

#we are going to "pretreat" the orginal files
#by de-compressing the vars that we want to compress

#Now upcompress the vars that we want to compress
#this is from running py2d.py
var2d= "Q2&T2&TH2&PSFC&U10&V10&SEAICE&ACSNOM&SNOW&SNOWH&CANWAT&SSTSK&COSZEN&LAI&TSK&RAINNCV&SWDOWN&GLW&SWNORM&ACSWUPT&ACSWUPTC&ACSWDNT&ACSWDNTC&ACSWU
